Kullanım Alanı: Menü gösterme, kullanıcıdan en az bir kez şifre isteme senaryoları.

private void Form1_Load(object sender, EventArgs e)
{
    cmbBanknotTipi.Items.Add("200 TL");
    cmbBanknotTipi.Items.Add("100 TL");
    cmbBanknotTipi.Items.Add("50 TL");
    cmbBanknotTipi.SelectedIndex = 0; // İlk elemanı seçili getir
}

private void btnParaCek_Click(object sender, EventArgs e)
{
    try
    {
        int cekilecek = Convert.ToInt32(txtTutar.Text);
        int banknot = 200;

        if (cmbBanknotTipi.SelectedIndex == 0) banknot = 200;
        else if (cmbBanknotTipi.SelectedIndex == 1) banknot = 100;
        else if (cmbBanknotTipi.SelectedIndex == 2) banknot = 50;

        listBoxFis.Items.Clear();
        int adet = 0;

        // WHILE DÖNGÜSÜ: Para yettiği sürece ver!
        while (cekilecek >= banknot)
        {
            adet++;
            cekilecek -= banknot; // Bakiyeden düş
            listBoxFis.Items.Add(adet + ". Banknot verildi: " + banknot + " TL (Kalan: " + cekilecek + " TL)");
        }
        lblKalan.Text = "Toplam " + adet + " adet verildi. Bozuk Kalan: " + cekilecek + " TL";
    }
    catch { MessageBox.Show("Lütfen geçerli bir tutar giriniz!"); }
}

